package com.innovatus.studentrecords.controller; import com.innovatus.studentrecords.dao.UserDAO; import com.innovatus.studentrecords.service.*; public class OTPController {private final OTPService otp=new OTPService();private final EmailService mail=new EmailService();private final AuthService auth=new AuthService();public void request(String email)throws Exception{if(new UserDAO().findByEmail(email).isEmpty())throw new IllegalArgumentException("No account uses that email.");mail.otp(email,otp.create());}public boolean verify(String code){return otp.verify(code);}public void reset(String email,String password)throws Exception{auth.reset(email,password);}}
